#include <map>
#include <iostream>

int main() {
    std::map<int, char> m = {{10, 'A'}, {20, 'B'}, {30, 'C'}};

    // Find the range for key 20
    auto range = m.equal_range(20);

    std::cout << "Lower bound key: " << range.first->first << "\n";

    // Find insertion point for 15
    auto it = m.lower_bound(15);

    // 15 would be inserted before 20
    if (it != m.end()) {
        std::cout << "15 inserts before: " << it->first << "\n"; 
    }
}
